const out='C:/AAAlilith/秋招投递/项目/PaperScope/runs/R06';
const claims=[
{id:'C01',statement:'摘要称 CrabNet 在总计 28 个基准数据集中的几乎全部达到或超过当前最佳实践方法；该句没有给出 steels_yield 的具体 MAE。',kind:'fact',verdict:'supported',evidence:[{source_id:'crabnet-incomplete',block_id:'p01-b01',quote:'Our results show that CrabNet’s performance matches or exceeds current best-practice methods on nearly all of 28 total benchmark datasets.'}],reasoning:'引文限定为 nearly all 和总体基准表现，没有指明 steels_yield，也没有给出其误差数值，不能用总体概括推出该数据集的比较结果。'},
{id:'C02',statement:'仅凭当前删减转换件，无法确定 CrabNet 在 steels_yield 上报告的 MAE 及单位。',kind:'unknown',verdict:'insufficient',evidence:[],reasoning:'检查范围为 crabnet-incomplete-原文定位.txt 的全部现存块，未见 steels_yield 结果条目、对应数值或单位。本次无全文 PDF；此结论不涉及完整论文是否报告。至少需要补充含该数据集 CrabNet MAE 的结果段或原表行，并保留列标题、单位和脚注。'},
{id:'C03',statement:'仅凭当前删减转换件，无法确定 Automatminer 在 steels_yield 上的对应 MAE 及单位。',kind:'unknown',verdict:'insufficient',evidence:[],reasoning:'检查范围为 crabnet-incomplete-原文定位.txt 的全部现存块，未见 Automatminer 的对应结果条目。不能从摘要概括推定基线数值，也不能从材料缺失推断完整论文没有报告。需要同一版本的 Automatminer 对应结果及其列标题、单位和脚注。'},
{id:'C04',statement:'当前材料不足以确定 CrabNet 相对 Automatminer 在 steels_yield 上的 MAE 改善量、百分比或改善方向。',kind:'unknown',verdict:'insufficient',evidence:[],reasoning:'缺少两种模型的对应 MAE 和可比性依据。若单位一致、设置可比，则绝对降低量为基线 MAE 减 CrabNet MAE；相对降低率需再除以非零基线 MAE 并乘 100%。缺少数值时，差值的大小及正负都不能确定。'},
{id:'C05',statement:'论文有意使用仅含组成、无结构信息的 EDM 表示。',kind:'fact',verdict:'supported',evidence:[{source_id:'crabnet-incomplete',block_id:'p06-b01',quote:'This work intentionally used a compositionally restricted EDM representation with no structural information.'}],reasoning:'引文直接说明该工作表示的组成限制及无结构信息条件，可作为补充结果后核对模型输入的依据。'},
{id:'C06',statement:'当前删减材料不足以核实 CrabNet 与 Automatminer 在 steels_yield 上的输入、样本范围、训练／测试划分及调参条件是否可比。',kind:'unknown',verdict:'insufficient',evidence:[],reasoning:'已检查整份转换件。现存方法段提供 CrabNet 的一般架构和训练信息，但没有两者针对 steels_yield 的成对比较设置；不可把一般默认参数当作双方相同评价协议的证明。需要补充同一版本的相应比较方法段或表格脚注。'}
];
const answer=`仅凭本次人为删减转换件，无法确定 CrabNet 在 \`steels_yield\` 上报告的 MAE，也无法确定 Automatminer 的对应 MAE，因此不能计算改善的绝对值、百分比，或断言该数据集上谁更好。[C02][C03][C04]

现有材料能核查的是：摘要称 CrabNet 在总计 28 个基准数据集中的“几乎全部”达到或超过最佳实践方法。这一总体表述不能确定 \`steels_yield\` 是否属于其中，也不提供该数据集的数值或 Automatminer 的对应结果。原文位置为转换件 \`crabnet-incomplete\`，块 \`p01-b01\`（标注 PDF 页序 1）。[C01]

另可确认，论文方法有意采用仅含组成、无结构信息的表示，见 \`p06-b01\`（标注 PDF 页序 6）。该条件有助于后续核对输入是否一致，但本附件不能确认 Automatminer 在 \`steels_yield\` 上的输入、样本范围、训练／测试划分和调参条件，尚不能判断这项数值比较是否可直接成立。[C05][C06]

缺口判断的范围是本目录提供的整份 \`crabnet-incomplete-原文定位.txt\`：已阅读其中全部现存块，未见 \`steels_yield\` 或 Automatminer 的结果条目及对应比较条件；本次没有提供全文 PDF。这是当前删减材料不足，不能据此认定完整论文没有报告这些结果，也不代表作者遗漏。[C02][C03][C06]

最小后续阅读动作是补充同一版本中含 \`steels_yield\` 结果的原始表格页或结果段落，保留 CrabNet、Automatminer 对应值、列标题、单位和脚注；若该页未交代比较设置，还需补充有关输入、样本范围、划分与调参的相关方法段。取得可比的两个 MAE 后，绝对降低量为 Automatminer MAE 减 CrabNet MAE，相对降低率为该差值除以 Automatminer MAE 再乘 100%（基线非零）；在此之前不填写数值。[C04][C06]
`;
const csv=`item,paper_setting,target_setting,comparability,evidence_ids
steels_yield MAE,当前删减件缺少 CrabNet 与 Automatminer 对应数值及单位,核查两模型的 MAE,unknown,C02;C03
改善量及方向,对应数值不足,计算绝对降低量和相对降低率,unknown,C04
输入信息,CrabNet 使用仅含组成且无结构信息的 EDM；Automatminer 对应输入未知,核查 steels_yield 上双方输入条件,unknown,C05;C06
样本与评价设置,缺少两者在 steels_yield 上的样本范围及划分和调参对应说明,核查数值是否来自可比设置,unknown,C06
`;
const files={'answer.md':answer,'claims.json':JSON.stringify({schema_version:'1.0',source_ids:['crabnet-incomplete'],claims},null,2),'comparison.csv':csv};
let cmd=`New-Item -ItemType Directory -Path '${out}' -Force | Out-Null\n`;
for(const [name,body] of Object.entries(files)) cmd+=`@'\n${body}\n'@ | Set-Content -LiteralPath '${out}/${name}' -Encoding utf8\n`;
cmd+=`Get-Item -LiteralPath '${out}/answer.md','${out}/claims.json','${out}/comparison.csv' | Select-Object FullName,Length`;
text(await tools.exec_command({cmd,max_output_tokens:1000}));
